// Music Player v4 (Tavern Helper / Spotify Edition)
(async () => {
try {
const doc = (window.parent || window).document;
console.log('[EBP] Starting...');
if (doc.getElementById('ebp-overlay')) { console.log('[EBP] Already loaded, skipping'); return; }
const EBP = ((window.parent || window)._ebp = {});

// ── Defaults ──
const LS = { PL:'ebp_playlists', APIS:'ebp_apis', VOL:'ebp_volume', MODE:'ebp_play_mode', AI:'ebp_ai_config' };
const DEFAULT_APIS = [
    {id:'netease-gd',name:'NetEase (GDStudio)',enabled:true,searchUrl:'https://music-api.gdstudio.xyz/api.php?types=search&count=5&source=netease&name={{query}}',getUrlApi:'https://music-api.gdstudio.xyz/api.php?types=url&source=netease&id={{id}}',searchResponsePath:'',songIdPath:'id',songNamePath:'name',artistPath:'artist',urlResponsePath:'url'},
    {id:'qq-vkeys',name:'QQ Music (VKeys)',enabled:true,searchUrl:'https://api.vkeys.cn/v2/music/tencent?word={{query}}',getUrlApi:'https://api.vkeys.cn/v2/music/tencent?id={{id}}',searchResponsePath:'data',songIdPath:'id',songNamePath:'song',artistPath:'singer',urlResponsePath:'data.url'},
    {id:'netease-vkeys',name:'NetEase (VKeys)',enabled:true,searchUrl:'https://api.vkeys.cn/v2/music/netease?word={{query}}',getUrlApi:'https://api.vkeys.cn/v2/music/netease?id={{id}}',searchResponsePath:'data',songIdPath:'id',songNamePath:'song',artistPath:'singer',urlResponsePath:'data.url'},
    {id:'kugou-meto',name:'Kugou (Meto)',enabled:true,searchUrl:'https://api.i-meto.com/meting/api?server=kugou&type=search&id={{query}}',getUrlApi:'https://api.i-meto.com/meting/api?server=kugou&type=song&id={{id}}',searchResponsePath:'',songIdPath:'id',songNamePath:'name',artistPath:'artist',urlResponsePath:'[0].url'}
];
const DEFAULT_COVER = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 80'%3E%3Crect width='80' height='80' fill='%23333'/%3E%3Ctext x='40' y='46' text-anchor='middle' font-size='28' fill='%23555'%3E%E2%99%AA%3C/text%3E%3C/svg%3E";

// ── State ──
let allPlaylists = {}, currentChatKey = 'global', playlist = [];
let currentTrack = null, currentIdx = -1;
const audio = new Audio();
let isPlaying = false, playMode = 0, apis = [], volume = 0.7;
let aiConfig = { msgCount: 20, songCount: 8, profile: '' };
let aiAbort = false, aiAbortCtrl = null, dragIdx = -1;

// ── Helpers ──
function P(o,p){if(!p)return o;if(p.startsWith('[')){const m=p.match(/^\[(\d+)\]\.?(.*)$/);if(m&&Array.isArray(o))return m[2]?P(o[parseInt(m[1])],m[2]):o[parseInt(m[1])];}let c=o;for(const k of p.split('.')){if(c==null)return;c=c[k];}return c;}
function fmt(s){return isNaN(s)?'0:00':Math.floor(s/60)+':'+Math.floor(s%60).toString().padStart(2,'0');}
function esc(s){const d=doc.createElement('div');d.textContent=s;return d.innerHTML;}

function getChatKey(){const c=SillyTavern.getContext();return c.characterId==null?'global':c.characterId+'_'+(c.chatId||'default');}
function getChatLabel(){return SillyTavern.getContext().name2||'Global';}
function copyTrackName(track,btnEl){
    const text=track.artist?track.name+' — '+track.artist:track.name;
    navigator.clipboard.writeText(text).then(()=>{
        toastr.success(text,'Скопировано');
        if(btnEl){btnEl.textContent='✓';setTimeout(()=>{btnEl.textContent='📋';},1000);}
    }).catch(()=>{
        const ta=doc.createElement('textarea');ta.value=text;ta.style.cssText='position:fixed;opacity:0';doc.body.appendChild(ta);ta.select();doc.execCommand('copy');ta.remove();
        toastr.success(text,'Скопировано');
        if(btnEl){btnEl.textContent='✓';setTimeout(()=>{btnEl.textContent='📋';},1000);}
    });
}

function getCover(track){
    if(track?.pic)return track.pic;
    try{const ctx=SillyTavern.getContext();const ch=ctx.characters?.[ctx.characterId];if(ch?.avatar)return '/thumbnail?type=avatar&file='+encodeURIComponent(ch.avatar);}catch(e){}
    return DEFAULT_COVER;
}

function getProfiles(){
    try{return SillyTavern.getContext().extensionSettings?.connectionManager?.profiles||[];}catch(e){return[];}
}

// ── Storage ──
function load(){try{const p=localStorage.getItem(LS.PL);if(p)allPlaylists=JSON.parse(p);const a=localStorage.getItem(LS.APIS);apis=a?JSON.parse(a):DEFAULT_APIS.map(x=>({...x}));const v=localStorage.getItem(LS.VOL);if(v)volume=parseFloat(v);const m=localStorage.getItem(LS.MODE);if(m)playMode=parseInt(m);const ai=localStorage.getItem(LS.AI);if(ai)aiConfig={...aiConfig,...JSON.parse(ai)};}catch(e){}}
function saveAll(){try{allPlaylists[currentChatKey]=playlist;localStorage.setItem(LS.PL,JSON.stringify(allPlaylists));}catch(e){}}
function saveApis(){try{localStorage.setItem(LS.APIS,JSON.stringify(apis));}catch(e){}}
function saveVol(){try{localStorage.setItem(LS.VOL,String(volume));}catch(e){}}
function saveMode(){try{localStorage.setItem(LS.MODE,String(playMode));}catch(e){}}
function saveAi(){try{localStorage.setItem(LS.AI,JSON.stringify(aiConfig));}catch(e){}}
function switchToChat(){const k=getChatKey();if(currentChatKey!=='global')allPlaylists[currentChatKey]=playlist;currentChatKey=k;playlist=allPlaylists[k]||[];allPlaylists[k]=playlist;saveAll();renderPlaylist();updatePlTab();}

// ═══ LLM CALL (direct, no ExtBlocks) ═══
async function callLLM(messages, profileId){
    const ctx=SillyTavern.getContext();
    const CMRS=ctx.ConnectionManagerRequestService;
    if(!CMRS)throw new Error('ConnectionManagerRequestService недоступен');

    aiAbortCtrl=new AbortController();
    try{
        const result=await CMRS.sendRequest(profileId, messages, 2048, {stream:false, signal:aiAbortCtrl.signal, extractData:true, includePreset:false});
        return(result?.content||'').trim();
    }finally{aiAbortCtrl=null;}
}

// ═══ MUSIC API ═══
async function searchSongs(query){
    const enabled=apis.filter(a=>a.enabled),results=[];
    for(const api of enabled){try{
        const res=await fetch(api.searchUrl.replace('{{query}}',encodeURIComponent(query)));
        const json=await res.json(),data=api.searchResponsePath?P(json,api.searchResponsePath):json;
        const items=Array.isArray(data)?data:(data?[data]:[]);
        for(const item of items.slice(0,5)){
            const sid=P(item,api.songIdPath);if(!sid)continue;
            const name=P(item,api.songNamePath)||'',ar=P(item,api.artistPath);
            const strAr=Array.isArray(ar)?ar.join(', '):(ar||'');
            const pic=P(item,'al.picUrl')||P(item,'pic')||P(item,'cover')||P(item,'album.cover_url')||P(item,'songinfo.pic')||null;
            results.push({name,artist:strAr,full:strAr?name+' - '+strAr:name,pic,_apiId:api.id,_songId:String(sid)});
        }
    }catch(e){}}
    return results;
}
async function getPlayUrl(apiId,songId){const api=apis.find(a=>a.id===apiId);if(!api)return null;try{const r=await fetch(api.getUrlApi.replace('{{id}}',songId));return P(await r.json(),api.urlResponsePath);}catch(e){return null;}}
function testUrl(url){return new Promise(r=>{if(!url){r(false);return;}const t=new Audio();t.preload='metadata';const d=v=>{t.onloadedmetadata=t.onerror=null;t.src='';r(v);};t.onloadedmetadata=()=>d(true);t.onerror=()=>d(false);t.src=url;setTimeout(()=>d(false),6000);});}

// ═══ AUDIO ENGINE ═══
async function playTrack(track,idx){
    if(!track)return;currentTrack=track;currentIdx=idx>=0?idx:playlist.indexOf(track);
    updateNow();
    let url=null;
    if(track._apiId&&track._songId){url=await getPlayUrl(track._apiId,track._songId);if(url&&!(await testUrl(url)))url=null;}
    if(!url){for(const api of apis.filter(a=>a.enabled)){try{
        const q=track.full||track.name;const sR=await fetch(api.searchUrl.replace('{{query}}',encodeURIComponent(q)));
        const sJ=await sR.json(),sD=api.searchResponsePath?P(sJ,api.searchResponsePath):sJ;
        const items=Array.isArray(sD)?sD:(sD?[sD]:[]);
        for(const item of items.slice(0,3)){const sid=P(item,api.songIdPath);if(!sid)continue;
            const u=await getPlayUrl(api.id,String(sid));
            if(u&&await testUrl(u)){url=u;track._apiId=api.id;track._songId=String(sid);
                if(!track.pic){track.pic=P(item,'al.picUrl')||P(item,'pic')||P(item,'cover')||null;if(track.pic)updateNow();}
                break;}}
        if(url)break;}catch(e){}}}
    if(!url){toastr.error('Трек не найден: '+(track.full||track.name),'EBP');nextTrack();return;}
    audio.src=url;audio.volume=volume;audio.play().catch(()=>{});isPlaying=true;
    updatePlayBtn();renderPlaylist();updateTB();
}
function togglePlay(){if(!currentTrack&&playlist.length>0){playTrack(playlist[0],0);return;}if(!currentTrack)return;if(isPlaying){audio.pause();isPlaying=false;}else{audio.play();isPlaying=true;}updatePlayBtn();updateTB();}
function nextTrack(){if(!playlist.length)return;if(playMode===1){playTrack(playlist[Math.floor(Math.random()*playlist.length)]);return;}playTrack(playlist[(currentIdx+1)%playlist.length],(currentIdx+1)%playlist.length);}
function prevTrack(){if(!playlist.length)return;const i=(currentIdx-1+playlist.length)%playlist.length;playTrack(playlist[i],i);}
function removeTrack(idx){const w=currentIdx===idx;playlist.splice(idx,1);saveAll();if(w){if(playlist.length>0){currentIdx=Math.min(idx,playlist.length-1);playTrack(playlist[currentIdx],currentIdx);}else{audio.pause();audio.src='';currentTrack=null;isPlaying=false;currentIdx=-1;updatePlayBtn();updateNow();updateTB();}}else if(currentIdx>idx)currentIdx--;renderPlaylist();}
function clearPlaylist(){const h=currentTrack&&playlist.some(t=>t.name===currentTrack.name&&t.artist===currentTrack.artist);playlist.length=0;allPlaylists[currentChatKey]=playlist;saveAll();if(h){audio.pause();audio.src='';currentTrack=null;isPlaying=false;currentIdx=-1;updatePlayBtn();updateNow();updateTB();}renderPlaylist();}
function addToPlaylist(t){if(playlist.some(x=>x.name===t.name&&x.artist===t.artist)){toastr.info('Уже в плейлисте','EBP');return;}playlist.push(t);saveAll();renderPlaylist();toastr.success(t.name,'Добавлено');}
function moveTrack(f,t){if(f===t||f<0||t<0||f>=playlist.length||t>=playlist.length)return;const[m]=playlist.splice(f,1);playlist.splice(t,0,m);if(currentIdx===f)currentIdx=t;else if(f<currentIdx&&t>=currentIdx)currentIdx--;else if(f>currentIdx&&t<=currentIdx)currentIdx++;saveAll();renderPlaylist();}
const MI=['↻','↔','⟳'],MT=['Повтор','Случайно','Один трек'];
function cycleMode(){playMode=(playMode+1)%3;saveMode();const b=doc.getElementById('ebp-mode');if(b){b.textContent=MI[playMode];b.title=MT[playMode];}}

// ═══ CHAT ANALYSIS ═══
let aiRunning=false;
async function analyzeChat(){
    if(aiRunning){aiAbort=true;if(aiAbortCtrl)aiAbortCtrl.abort();return;}
    const ctx=SillyTavern.getContext();if(ctx.characterId==null){toastr.error('Откройте чат','EBP');return;}

    const $s=doc.getElementById('ebp-ai-status'),$b=doc.getElementById('ebp-ai-btn'),$bar=doc.getElementById('ebp-ai-bar');
    function setStatus(html){if($s)$s.innerHTML=html;}
    function setProgress(pct){if($bar)$bar.style.width=pct+'%';}
    function setBtnCancel(){if($b)$b.textContent='⏹ Отмена';aiRunning=true;}
    function setBtnReady(){if($b)$b.textContent='🎵 Подобрать музыку';aiRunning=false;}

    const chat=ctx.chat,mc=Math.min(aiConfig.msgCount,chat.length),sc=aiConfig.songCount;
    const un=ctx.name1||'User',cn=ctx.name2||'Char';
    const msgs=chat.slice(-mc).filter(m=>!m.is_system).map(m=>(m.is_user?un:cn)+': '+(m.mes||'').substring(0,400)).join('\n');
    const defs=[];const cd=ctx.characters?.[ctx.characterId];
    if(cd?.data?.description)defs.push('Char: '+cd.data.description.substring(0,500));
    if(cd?.data?.personality)defs.push('Personality: '+cd.data.personality.substring(0,300));
    const wantEl=doc.getElementById('ebp-ai-want'),skipEl=doc.getElementById('ebp-ai-skip');
    const want=(wantEl?.value||'').trim(),skip=(skipEl?.value||'').trim();
    let sysPr='You are a music recommendation assistant. Analyze the roleplay chat below. Suggest '+sc+' songs matching mood, atmosphere, emotions, themes. Prefer well-known songs.';
    if(want)sysPr+=' User preferences: '+want+'.';
    if(skip)sysPr+=' AVOID these genres/artists/styles: '+skip+'.';
    sysPr+=' Output ONLY valid JSON: [{"name":"Title","artist":"Artist"}, ...]. No other text.';
    const pr=[{role:'system',content:sysPr},{role:'user',content:(defs.length?defs.join('\n')+'\n\n':'')+'Chat ('+mc+' msgs):\n'+msgs+'\n\nSuggest '+sc+' songs:'}];

    aiAbort=false;setBtnCancel();setProgress(0);
    try{
        setStatus('⏳ Отправляю чат на анализ...');setProgress(5);
        let text=await callLLM(pr,aiConfig.profile);
        if(aiAbort){setStatus('Отменено');setProgress(0);return;}
        setProgress(20);
        text=text.replace(/```json?\s*/g,'').replace(/```\s*/g,'').trim();
        let songs;
        try{songs=JSON.parse(text);}catch(e){const m=text.match(/\[[\s\S]*\]/);if(m)songs=JSON.parse(m[0]);else throw new Error('LLM вернула невалидный JSON');}
        if(!Array.isArray(songs)||!songs.length){setStatus('LLM не дала рекомендаций. Попробуйте ещё раз.');setProgress(0);return;}

        setStatus('Подобрано: <b>'+songs.length+'</b> песен. Ищу в API...');
        let found=0,failed=0;
        for(let i=0;i<songs.length;i++){
            if(aiAbort){setStatus('Отменено. Добавлено: <b>'+found+'</b>');break;}
            const sn=songs[i].name||'?',sa=songs[i].artist||'';const q=sa?sn+' '+sa:sn;
            const pct=20+Math.round(((i+1)/songs.length)*80);
            setProgress(pct);
            setStatus('Подобрано: <b>'+songs.length+'</b><br>🔍 <b>'+esc(sn)+'</b>'+(sa?' — '+esc(sa):'')+'<br><span style="color:var(--t3)">'+(i+1)+' из '+songs.length+' · ✅ '+found+' · ❌ '+failed+'</span>');
            const r=await searchSongs(q);
            if(r.length>0&&!playlist.some(t=>t.name===r[0].name&&t.artist===r[0].artist)){playlist.push(r[0]);saveAll();found++;}else{failed++;}
        }
        if(!aiAbort){setStatus('✅ Готово! Добавлено: <b>'+found+'</b> из '+songs.length+(failed?' · не найдено: '+failed:''));setProgress(100);}
        renderPlaylist();
    }catch(e){
        setStatus('❌ Ошибка: '+esc(e.message)+'<br><span style="color:var(--t3)">Нажмите кнопку чтобы попробовать снова</span>');
        setProgress(0);
    }finally{setBtnReady();}
}

// ═══ CSS — Spotify Dark ═══
const css=doc.createElement('style');css.id='ebp-styles';
css.textContent=`
#ebp-toolbar-btn{position:relative;cursor:pointer;font-size:18px;opacity:0.6;transition:all 0.2s;padding:2px 4px}
#ebp-toolbar-btn:hover{opacity:1}
#ebp-toolbar-btn.active{opacity:1;color:#1DB954}
#ebp-toolbar-btn .ebp-dot{position:absolute;top:-2px;right:-4px;width:7px;height:7px;border-radius:50%;background:#1DB954;display:none}
#ebp-toolbar-btn.playing .ebp-dot{display:block;animation:ebp-p 1.5s infinite}
@keyframes ebp-p{0%,100%{opacity:1}50%{opacity:.3}}
#ebp-fab{display:none;position:fixed;bottom:70px;right:12px;z-index:1999999;width:44px;height:44px;border-radius:50%;background:#1DB954;color:#000;border:none;box-shadow:0 4px 12px rgba(0,0,0,.4);cursor:pointer;align-items:center;justify-content:center;font-size:20px;-webkit-tap-highlight-color:transparent}
#ebp-fab:active{transform:scale(0.9)}
#ebp-fab .ebp-dot{position:absolute;top:2px;right:2px;width:8px;height:8px;border-radius:50%;background:#fff;display:none}
#ebp-fab.playing .ebp-dot{display:block;animation:ebp-p 1.5s infinite}
@media(max-width:768px){#ebp-fab{display:flex}}

#ebp-overlay{position:fixed;top:0;left:0;width:100vw;height:100vh;height:100dvh;background:rgba(0,0,0,.75);z-index:2000000;display:flex;align-items:center;justify-content:center;padding:20px;overflow-y:auto;-webkit-overflow-scrolling:touch;box-sizing:border-box}
@media(max-width:768px){#ebp-overlay{padding:10px}}
@media(max-height:700px){#ebp-cover-wrap{width:100px!important;height:100px!important}#ebp-now{padding:10px 16px 6px}#ebp-ctrl{gap:12px}}
#ebp-root{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:13px;width:380px;max-width:100%;max-height:calc(100dvh - 40px);overflow-y:auto;border-radius:12px;
--bg0:#121212;--bg1:#181818;--bg2:#282828;--bg3:#333;--green:#1DB954;--green2:#1ed760;--t1:#fff;--t2:#b3b3b3;--t3:#727272;
background:var(--bg1);color:var(--t1);border:1px solid rgba(255,255,255,.06);box-shadow:0 16px 48px rgba(0,0,0,.6),0 4px 12px rgba(0,0,0,.4);flex-shrink:0;scrollbar-width:thin}
#ebp-root::-webkit-scrollbar{width:4px}
#ebp-root::-webkit-scrollbar-thumb{background:var(--bg3);border-radius:2px}
@media(max-width:768px){#ebp-root{width:95vw;max-height:80vh;border-radius:16px}}

#ebp-hdr{display:flex;align-items:center;padding:12px 16px;gap:8px;user-select:none;background:var(--bg0)}
#ebp-hdr-t{flex:1;font-size:12px;font-weight:700;color:var(--green);letter-spacing:.5px}
#ebp-hdr-n{flex:2;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:center;color:var(--t2)}
.ebp-hb{background:none;border:none;color:var(--t3);cursor:pointer;font-size:15px;padding:4px;border-radius:50%;transition:all .15s}
.ebp-hb:hover{color:var(--t1);background:var(--bg2)}

#ebp-now{padding:20px 24px 12px;text-align:center;background:linear-gradient(180deg,var(--bg2) 0%,var(--bg1) 100%)}
#ebp-cover-wrap{width:180px;height:180px;margin:0 auto 16px;border-radius:8px;overflow:hidden;box-shadow:0 8px 24px rgba(0,0,0,.5)}
#ebp-cover{width:100%;height:100%;object-fit:cover;display:block}
#ebp-name{font-size:16px;font-weight:700;margin-bottom:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#ebp-artist{font-size:13px;color:var(--t2);margin-bottom:14px}
#ebp-prog{height:4px;background:var(--bg3);border-radius:2px;cursor:pointer;margin-bottom:6px;position:relative;transition:height .15s}
#ebp-prog:hover{height:6px}
#ebp-fill{height:100%;background:var(--green);border-radius:2px;width:0%;position:relative;transition:width .1s linear}
#ebp-prog:hover #ebp-fill::after{content:'';position:absolute;right:-5px;top:50%;transform:translateY(-50%);width:12px;height:12px;background:#fff;border-radius:50%;box-shadow:0 2px 4px rgba(0,0,0,.3)}
#ebp-time{display:flex;justify-content:space-between;font-size:11px;color:var(--t3);margin-bottom:12px;font-variant-numeric:tabular-nums}
#ebp-ctrl{display:flex;justify-content:center;align-items:center;gap:16px}
.ebp-cb{width:32px;height:32px;border:none;border-radius:50%;background:transparent;color:var(--t2);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:14px;transition:all .15s;padding:0}
.ebp-cb:hover{color:var(--t1);transform:scale(1.05)}
#ebp-play{width:48px;height:48px;background:var(--green);color:#000;font-size:18px;font-weight:700}
#ebp-play:hover{background:var(--green2);transform:scale(1.06)}
#ebp-vol-w{display:flex;align-items:center;gap:8px;margin-top:12px;justify-content:center}
#ebp-vol-i{font-size:14px;color:var(--t2)}
#ebp-vol{width:100px;height:4px;-webkit-appearance:none;appearance:none;background:var(--bg3);border-radius:2px;outline:none;cursor:pointer}
#ebp-vol::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:#fff;cursor:pointer;box-shadow:0 1px 3px rgba(0,0,0,.3)}

#ebp-tabs{display:flex;background:var(--bg0);border-top:1px solid rgba(255,255,255,.04);border-bottom:1px solid rgba(255,255,255,.04)}
.ebp-tab{flex:1;padding:10px 0;text-align:center;font-size:11px;font-weight:600;color:var(--t3);cursor:pointer;border:none;background:none;transition:color .15s;border-bottom:2px solid transparent}
.ebp-tab:hover{color:var(--t2)}
.ebp-tab.on{color:var(--t1);border-bottom-color:var(--green)}
#ebp-panels{max-height:300px;overflow-y:auto;scrollbar-width:thin;background:var(--bg1)}
#ebp-panels::-webkit-scrollbar{width:6px}
#ebp-panels::-webkit-scrollbar-thumb{background:var(--bg3);border-radius:3px}
.ebp-pn{display:none;padding:8px}
.ebp-pn.on{display:block}

.ebp-plh{display:flex;align-items:center;justify-content:space-between;padding:6px 8px;margin-bottom:4px}
.ebp-plh-l{font-size:12px;color:var(--green);font-weight:700}
.ebp-plh-c{font-size:10px;color:var(--t3)}
.ebp-plh-x{font-size:10px;color:var(--t3);cursor:pointer;border:none;background:none;padding:4px 8px;border-radius:12px;font-weight:600;transition:all .15s}
.ebp-plh-x:hover{color:#e74c3c;background:rgba(231,76,60,.1)}

.ebp-tr{display:flex;align-items:center;gap:10px;padding:6px 8px;border-radius:6px;cursor:pointer;transition:background .15s;border:2px solid transparent;position:relative}
.ebp-tr:hover{background:var(--bg2)}
.ebp-tr.now{background:rgba(29,185,84,.08)}
.ebp-tr.now .ebp-tr-n{color:var(--green)}
.ebp-tr.now::before{content:'';position:absolute;left:0;top:20%;bottom:20%;width:3px;background:var(--green);border-radius:2px}
.ebp-tr.drag-over{border-top-color:var(--green)}
.ebp-tr.dragging{opacity:.3}
