.ebp-in:focus{border-color:var(--t2)}
.ebp-go{padding:8px 18px;background:var(--green);color:#000;border:none;border-radius:20px;font-size:13px;font-weight:700;cursor:pointer;transition:background .15s}
.ebp-go:hover{background:var(--green2)}

.ebp-sr{display:flex;align-items:center;gap:10px;padding:8px;border-radius:6px;transition:background .15s}
