.ebp-sr-i{flex:1;min-width:0}
.ebp-sr-n{font-size:13px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ebp-sr-a{font-size:11px;color:var(--t2)}
.ebp-sr-copy,.ebp-sr-play,.ebp-sr-add{width:28px;height:28px;border-radius:50%;border:1px solid var(--t3);background:none;color:var(--t2);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:14px;transition:all .15s;flex-shrink:0}
.ebp-sr-copy:hover{border-color:var(--green);color:var(--green);transform:scale(1.1)}
.ebp-sr-play:hover{border-color:var(--green);color:var(--green);transform:scale(1.1)}
.ebp-sr-add:hover{border-color:var(--t1);color:var(--t1);transform:scale(1.1)}

.ebp-lbl{font-size:12px;color:var(--t2);margin-bottom:8px;font-weight:600}
.ebp-row{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.ebp-row span{font-size:12px;min-width:110px;color:var(--t2)}
.ebp-num{width:64px;padding:6px 10px;background:var(--bg2);color:var(--t1);border:1px solid var(--bg3);border-radius:6px;font-size:13px;text-align:center;outline:none}
.ebp-sel{padding:6px 10px;background:var(--bg2);color:var(--t1);border:1px solid var(--bg3);border-radius:6px;font-size:13px;outline:none;cursor:pointer;max-width:180px}
#ebp-ai-bar-wrap{height:4px;background:var(--bg3);border-radius:2px;margin-top:8px;overflow:hidden}
#ebp-ai-bar{height:100%;width:0%;background:var(--green);border-radius:2px;transition:width 0.3s ease}
#ebp-ai-st{font-size:11px;color:var(--t2);margin-top:8px;min-height:16px;word-break:break-word;line-height:1.5}
