// ═══ UI ═══
function updatePlayBtn(){const b=doc.getElementById('ebp-play');if(b)b.textContent=isPlaying?'❚❚':'▶';}
function updateNow(){
    const $n=doc.getElementById('ebp-name'),$a=doc.getElementById('ebp-artist'),$h=doc.getElementById('ebp-hdr-n'),$c=doc.getElementById('ebp-cover');
    if($n)$n.textContent=currentTrack?currentTrack.name:'Нет трека';
    if($a)$a.textContent=currentTrack?(currentTrack.artist||''):'';
    if($h)$h.textContent=currentTrack?(currentTrack.full||currentTrack.name):'---';
    if($c)$c.src=getCover(currentTrack);
}
function updatePlTab(){const $t=root.querySelector('.ebp-tab[data-t="pl"]');if($t){const l=getChatLabel(),c=playlist.length;$t.textContent=c>0?l+' ('+c+')':'Плейлист';}}

function populateProfileSelect(){
    const $sel=doc.getElementById('ebp-ai-p');if(!$sel)return;
    const profiles=getProfiles();
    $sel.innerHTML=profiles.map(p=>'<option value="'+esc(p.id)+'"'+(aiConfig.profile===p.id?' selected':'')+'>'+esc(p.name)+' ('+esc(p.model||'?')+')</option>').join('');
    if((!aiConfig.profile||!profiles.find(p=>p.id===aiConfig.profile))&&profiles.length>0){aiConfig.profile=profiles[0].id;saveAi();}
}

function renderPlaylist(){
    const $=doc.getElementById('ebp-p-pl');if(!$)return;updatePlTab();
    if(!playlist.length){$.innerHTML='<div class="ebp-plh"><span class="ebp-plh-l">♫ '+esc(getChatLabel())+'</span></div><div class="ebp-empty">Плейлист пуст<br>Поиск или AI добавят треки</div>';return;}
    let h='<div class="ebp-plh"><span class="ebp-plh-l">♫ '+esc(getChatLabel())+'</span><span class="ebp-plh-c">'+playlist.length+' трек(ов)</span><button class="ebp-plh-x" id="ebp-clr">Очистить</button></div>';
    h+=playlist.map((t,i)=>{const p=currentTrack&&t.name===currentTrack.name&&t.artist===currentTrack.artist;
        return '<div class="ebp-tr'+(p?' now':'')+'" draggable="true" data-i="'+i+'">'+
        '<span class="ebp-tr-grip">⠿</span>'+
        '<img class="ebp-tr-img" src="'+esc(getCover(t))+'" onerror="this.src=\''+DEFAULT_COVER+'\'">'+
        '<div class="ebp-tr-info"><div class="ebp-tr-n">'+esc(t.name)+'</div>'+(t.artist?'<div class="ebp-tr-a">'+esc(t.artist)+'</div>':'')+'</div>'+
        '<span class="ebp-tr-copy" data-c="'+i+'" title="Копировать">📋</span><span class="ebp-tr-del" data-d="'+i+'">×</span></div>';}).join('');
    $.innerHTML=h;
    $J('#ebp-p-pl').off('.ebp');
    $J('#ebp-p-pl').on('click.ebp','.ebp-tr',function(e){if($J(e.target).closest('.ebp-tr-del,.ebp-tr-grip,.ebp-tr-copy').length)return;playTrack(playlist[parseInt(this.dataset.i)],parseInt(this.dataset.i));});
    $J('#ebp-p-pl').on('click.ebp','.ebp-tr-del',function(e){e.stopPropagation();removeTrack(parseInt(this.dataset.d));});
    $J('#ebp-p-pl').on('click.ebp','.ebp-tr-copy',function(e){e.stopPropagation();const t=playlist[parseInt(this.dataset.c)];if(t)copyTrackName(t,this);});
    $J('#ebp-p-pl').on('click.ebp','#ebp-clr',clearPlaylist);
    // drag-and-drop uses native events (they work on elements in parent doc)
    $.querySelectorAll('.ebp-tr').forEach(el=>{
        el.addEventListener('dragstart',e=>{dragIdx=parseInt(el.dataset.i);el.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragIdx);});
        el.addEventListener('dragend',()=>{el.classList.remove('dragging');$.querySelectorAll('.ebp-tr').forEach(x=>x.classList.remove('drag-over'));dragIdx=-1;});
        el.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';$.querySelectorAll('.ebp-tr').forEach(x=>x.classList.remove('drag-over'));if(parseInt(el.dataset.i)!==dragIdx)el.classList.add('drag-over');});
        el.addEventListener('dragleave',()=>el.classList.remove('drag-over'));
        el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drag-over');const to=parseInt(el.dataset.i);if(dragIdx>=0&&dragIdx!==to)moveTrack(dragIdx,to);});
    });
}

let lastSearchResults=[];
function renderSR(res){
    lastSearchResults=res;
    const $=doc.getElementById('ebp-sres');if(!$)return;
    if(!res.length){$.innerHTML='<div class="ebp-empty">Ничего не найдено</div>';return;}
    $.innerHTML=res.map((t,i)=>'<div class="ebp-sr"><img class="ebp-sr-img" src="'+esc(getCover(t))+'" onerror="this.src=\''+DEFAULT_COVER+'\'"><div class="ebp-sr-i"><div class="ebp-sr-n">'+esc(t.name)+'</div><div class="ebp-sr-a">'+esc(t.artist)+'</div></div><button class="ebp-sr-copy" data-i="'+i+'" title="Копировать">📋</button><button class="ebp-sr-play" data-i="'+i+'" title="Послушать">▶</button><button class="ebp-sr-add" data-i="'+i+'" title="В плейлист">+</button></div>').join('');
    $J('#ebp-sres').off('.ebp')
        .on('click.ebp','.ebp-sr-copy',function(){const t=lastSearchResults[parseInt(this.dataset.i)];if(t)copyTrackName(t,this);})
        .on('click.ebp','.ebp-sr-add',function(){addToPlaylist(lastSearchResults[parseInt(this.dataset.i)]);})
        .on('click.ebp','.ebp-sr-play',async function(){
            const t=lastSearchResults[parseInt(this.dataset.i)];if(!t)return;
            this.textContent='...';
            let url=null;
            if(t._apiId&&t._songId){url=await getPlayUrl(t._apiId,t._songId);if(url&&!(await testUrl(url)))url=null;}
            if(!url){toastr.error('Не удалось получить ссылку','EBP');this.textContent='▶';return;}
            audio.src=url;audio.volume=volume;audio.play().catch(()=>{});
            isPlaying=true;currentTrack=t;currentIdx=-1;
            updateNow();updatePlayBtn();updateTB();
            this.textContent='▶';
        });
}

function renderApi(){
    const $=doc.getElementById('ebp-p-api');if(!$)return;
    $.innerHTML='<div class="ebp-lbl">Источники музыки</div>'+apis.map((a,i)=>'<div class="ebp-api"><input type="checkbox" class="ebp-api-t" data-i="'+i+'" '+(a.enabled?'checked':'')+'><span class="ebp-api-n">'+esc(a.name)+'</span></div>').join('')+'<button class="ebp-go" id="ebp-api-r" style="width:100%;margin-top:10px;background:var(--bg2);color:var(--t2);border:1px solid var(--bg3)">По умолчанию</button>';
    $J('#ebp-p-api').off('.ebp');
    $J('#ebp-p-api').on('change.ebp','.ebp-api-t',function(){apis[parseInt(this.dataset.i)].enabled=this.checked;saveApis();});
    $J('#ebp-p-api').on('click.ebp','#ebp-api-r',function(){apis=DEFAULT_APIS.map(a=>({...a}));saveApis();renderApi();});
}

